import { runCompletionCheckerControls } from './scripts/h02-progress/completion-checker-controls.ts';
import { createCompletionModel, stepCompletionModel, modelCompletionView, checkCompletionObservation } from './packages/query-db-collection/tests/queued-answer-completion-oracle.ts';
const controls=runCompletionCheckerControls();
const setup={run:'one',profile:'inline',ready:true,window:{offset:0,limit:1},facts:{roots:[{id:1,rank:10}],marked:[],children:[]}};
const m=createCompletionModel(setup);stepCompletionModel(m,{type:'require',requirement:{id:'tail',kind:'publication'}});stepCompletionModel(m,{type:'request-window',operation:'old',options:{},requires:['tail']});
const common={phase:'candidate-cut',run:m.run,view:modelCompletionView(m),operations:[{operation:'old',returned:'promise',outcome:{state:'pending'}}]};
const extras=[{name:'missing required existingOperation at host gap',observation:{...common,cut:'host-gap',answerExecuted:true,demandSettled:true,queuedTask:1,dispatches:0}},{name:'missing error and absent authored failure at tail-failed',observation:{...common,cut:'tail-failed',lastReceiptSettled:true,realTailEntered:true,inputBefore:1,inputAfter:1,windowBefore:1,windowAfter:1}}];
const additional=extras.map(({name,observation})=>{try{checkCompletionObservation(m,observation);return{name,outcome:'accepted'};}catch(error){return{name,outcome:'rejected',error:String(error)};}});
console.log(JSON.stringify({controls,accepted:controls.filter(v=>v.outcome==='accepted').length,rejected:controls.filter(v=>v.outcome==='rejected').length,additional,receiving:0,generatedHistories:0,productionImports:0,productMutants:0}));
